const signalsWorkspace=()=>{const w=document.createElement('section');w.className='signals-workspace';const h=document.createElement('header');h.className='radar-risk-hero';h.innerHTML='<div><p class="eyebrow">RADAR / SIGNALS</p><h2>Signals</h2><p>Отобранные события из подтверждённых источников. FACT ≠ ANALYSIS ≠ DECISION.</p></div>';const feed=newsSignals();w.append(h);if(feed.length){const grid=document.createElement('div');grid.className='owner-news-grid signals-news-grid';grid.append(...feed.map(signalNewsCard));w.append(grid)}const proven=signals.filter(s=>['LONG','SHORT'].includes(s.direction)&&['LIVE','OK'].includes(s.quality)&&s.source_ref&&s.published_at);if(proven.length)w.append(...proven.map(signalTradeCard));if(!feed.length&&!proven.length)w.append(signalTradeCard({}));return w};
const todayBaseIndicators=()=>{const w=document.createElement('section');w.className='today-base-indicators';const h=document.createElement('header');h.innerHTML='<div><p class="eyebrow">TODAY / BASELINE</p><h2>Итоговые индикаторы</h2></div><span>fail-closed · только подтверждённые источники</span>';w.append(h);const grid=document.createElement('div');grid.className='today-indicator-grid';const m=window.RADAR_MARKET,r=window.RADAR_RUBLE,now=new Date(),mp=m?.published_at?new Date(m.published_at):null,marketFresh=mp&&!Number.isNaN(mp)&&((now-mp)/86400000)<=2,marketState=m?.data?.crash?.state||'N/A',marketDir=marketFresh&&m?.data?.direction?.quality==='LIVE'&&m?.data?.direction?.value?m.data.direction.value:'N/A';const cards=[{name:'MARKET',value:marketState,trend:marketDir,fresh:marketFresh?'АКТУАЛЬНО':'STALE',note:mp?'Источник: '+mp.toLocaleDateString('ru-RU'):'Источник недоступен',tone:marketState==='NORMAL'?'good':'warn'},{name:'RADAR',value:marketState==='N/A'?'N/A':'RISK · '+marketState,trend:marketDir,fresh:marketFresh?'АКТУАЛЬНО':'STALE',note:'MOEX Crash Radar · '+(mp?mp.toLocaleDateString('ru-RU'):'N/A'),tone:marketState==='NORMAL'?'good':'warn'},{name:'USD/RUB',value:r?.headline?.rate||'N/A',trend:r?.headline?.ruble_direction?((r.headline.ruble_direction==='УКРЕПЛЕНИЕ'?'↓ USD/RUB · ':'↑ USD/RUB · ')+r.headline.ruble_direction+' RUB'):'N/A',fresh:r?.headline?.source_date===new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}).format(now)?'АКТУАЛЬНО':'STALE',note:r?.headline?.change_1d?String(r.headline.change_1d)+' за день · '+String(r.headline.source_date||''):'нет свежих данных',tone:r?.headline?.ruble_direction==='УКРЕПЛЕНИЕ'?'good':'warn'}];cards.forEach(x=>{const c=document.createElement('article');c.className='today-indicator '+x.tone;c.innerHTML='<div><span>'+text(x.name)+'</span><em>'+text(x.fresh)+'</em></div><strong>'+text(x.value)+'</strong><b>'+text(x.trend)+'</b><small>'+text(x.note)+'</small>';grid.append(c)});w.append(grid);return w};
const renderView=view=>{view=view==='TODAY'?'ALL':view;const isP=view==='PORTFOLIO',isRadar=view==='RADAR',isIdeas=view==='IDEAS',isSignals=view==='SIGNALS',isMarket=view==='MARKET',isWorkspace=isP||isRadar||isIdeas||isSignals||isMarket;document.body.classList.toggle('portfolio-mode',isP);document.body.classList.toggle('radar-mode',isRadar);[summary,market,panelHeading].forEach(el=>{if(el)el.hidden=isWorkspace});if(isP){const d=portfolios.find(p=>p.portfolio_id===activePortfolio)||portfolios[0];list.classList.add('has-portfolio');list.replaceChildren(portfolioTabs(),...(d?[workspace(d)]:[]));empty.hidden=!!d;return}if(isRadar){list.classList.add('has-portfolio');list.replaceChildren(radarRiskWorkspace());empty.hidden=true;return}if(isIdeas){list.classList.remove('has-portfolio');list.replaceChildren(...ideas.map(ideaCard));itemCount.textContent=ideas.length;criticalCount.textContent=0;empty.hidden=ideas.length>0;return}if(isSignals){list.classList.add('has-portfolio');list.replaceChildren(signalsWorkspace());empty.hidden=true;return}const visible=view==='ALL'?today.filter(d=>d.context!=='MARKET'):today.filter(d=>d.context===view);list.classList.remove('has-portfolio');list.replaceChildren(...(view==='ALL'?[todayBaseIndicators()]:[]),...visible.map(createDecision));itemCount.textContent=visible.length;criticalCount.textContent=visible.filter(i=>i.priority==='CRITICAL').length;empty.hidden=visible.length>0};
document.querySelectorAll('.view-tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.view-tab').forEach(x=>x.classList.toggle('is-active',x===b));renderView(b.dataset.view)});Promise.all([applyMasterOwnerPortfolio(),loadTradeJournal()]).finally(()=>renderView('ALL'));
